output:
server {
    listen 80;
    server_name www.static.example;
    root /var/www/site;
    location / {
        try_files $uri $uri/ =404;
    }
}

location / {
    root /var/www/react-app;
    try_files $uri $uri/ /index.html;
}

location /app {
    root /var/www;
    try_files $uri $uri/ /app/index.html;
}

location /assets/ {
    root /var/www/site;
    expires 1y;
    add_header Cache-Control "public, max-age=31536000, immutable";
}

location /images/ {
    root /var/www/site;
    expires 7d;
    add_header Cache-Control "public, max-age=604800";
}

location ~* \.(zip|gz|tgz|exe)$ {
    root /var/www;
    charset off;
}

location /pub/ftp/ {
    alias /srv/ftp/;
    autoindex on;
    autoindex_exact_size off;
    autoindex_localtime on;
    charset utf-8;
}

server {
    listen 80;
    server_name files.example.com;
    root /var/www/files;
    autoindex off;
    location / {
        try_files $uri $uri/ =404;
    }
}

location = /favicon.ico {
    root /var/www/seo;
    access_log off;
    log_not_found off;
}
location = /robots.txt {
    root /var/www/seo;
    access_log off;
}

location /videos/ {
    root /var/www;
    mp4;
    mp4_buffer_size 1m;
    mp4_max_buffer_size 5m;
}

location = /dl/latest-report.csv {
    root /var/www;
    add_header Content-Disposition 'attachment; filename="latest-report.csv"' always;
}

location ~ /\.(?!well-known) {
    deny all;
}
location ^~ /.well-known/acme-challenge/ {
    root /var/www/certbot;
}

location / {
    root /var/www/brand;
    try_files $uri $uri/ @notfound;
}
location @notfound {
    root /var/www/brand;
    try_files /404.html =404;
}

location /admin {
    root /var/www/html;
    try_files $uri $uri/ /admin/index.html;
}

location /modules/ {
    root /var/www;
    types {
        text/javascript mjs js;
        application/json json;
        text/css css;
        application/wasm wasm;
        text/html html;
    }
}

location /media/ {
    root /var/www;
    sendfile on;
    tcp_nodelay on;
    aio threads;
    directio 8m;
    output_buffers 2 1m;
}

server {
    listen 80;
    server_name docs-old.example.com;
    root /var/www/docs-old;
    error_page 404 /404.html;
    location / {
        try_files $uri $uri/ =404;
    }
    location = /404.html {
        internal;
    }
}

location /data/ {
    alias /srv/repository/;
    autoindex on;
    charset utf-8;
}

location ~* \.(bak|conf|sql|old|orig)$ {
    deny all;
}

location = /index.html {
    root /var/www/app;
    add_header Cache-Control "no-store, no-cache, must-revalidate";
    expires -1;
}
location /static/ {
    root /var/www/app;
    expires 1y;
    add_header Cache-Control "public, immutable";
}
